const RAIL_D = 1.4, WIRE_D = 1.2, RECESS = 0.1, RAIL_Y = 3.0;
const band = ringShank({ ring_size: { system: 'US', size: '7' }, band_width: 2.4, band_thickness: 1.6, band_profile: 'comfort_fit' });
const ri = band.dims.innerDiameterMm / 2;
const ro = band.dims.outerDiameterMm / 2;
const railR = RAIL_D / 2, wireR = WIRE_D / 2;
const railC = ri + RECESS + railR;
const wireC = railC;
const D2R = Math.PI / 180;
function P(phi, y, r) { return [r * Math.sin(phi * D2R), y, r * Math.cos(phi * D2R)]; }

const railA = torus(railC, railR).rotate([90, 0, 0]).translate([0, RAIL_Y, 0]);
const railB = torus(railC, railR).rotate([90, 0, 0]).translate([0, -RAIL_Y, 0]);

const PHI0 = 60, PHI1 = 300, WAVES = 5, N = 200;
function wavePts(s) {
  const pts = [];
  for (let i = 0; i <= N; i++) {
    const phi = PHI0 + (PHI1 - PHI0) * i / N;
    const t = (i / N) * WAVES * 2 * Math.PI;
    pts.push(P(phi, s * RAIL_Y * (0.5 + 0.5 * Math.cos(t)), wireC));
  }
  return pts;
}
const waveA = sweep(wireR, wavePts(1));
const waveB = sweep(wireR, wavePts(-1));

const openwork = union(railA, railB, waveA, waveB).named('openwork');

const moon = cabochon({ length: 8, width: 6, height: 3.5, orientation: 'east_west', name: 'moonstone' });
const setting = bezel({ stone: moon, on: band, wall: 1.0, lip: 1.4 });

const bb = setting.bounds();
const ga = bb.max[0] - 0.45, gb = bb.max[1] - 0.15;
const pad = cylinder(1, ro).scale([ga, gb, 1]);
const hole = cylinder(ri + RECESS, 30, { center: true }).rotate([90, 0, 0]);
const gallery = difference(pad, hole).named('gallery');

return union(band, openwork, gallery, setting);

