programs.fluted-petals:
const band = ringShank({ ring_size: { system: 'US', size: '7' }, band_width: '2.0 mm', band_thickness: '2.0 mm', band_profile: 'round' });
const bandTop = band.dims.outerDiameterMm / 2;
const cupBottom = bandTop + 0.64;
const CUP_OUT = 3.2, CUP_IN = 2.2, CUP_H = 3.0, FLOOR = 1.2;
const cupBowl = revolve(polygon([[0, 0], [CUP_OUT, 0], [CUP_OUT, CUP_H], [CUP_IN, CUP_H], [CUP_IN, FLOOR], [0, FLOOR]])).translate([0, 0, cupBottom]);
const postBottom = bandTop - 0.76;
const post = cylinder(1.2, cupBottom + 0.4 - postBottom).translate([0, 0, postBottom]);
const cup = union(cupBowl, post).named('cup');
const floorZ = cupBottom + FLOOR;
const rimZ = cupBottom + CUP_H;
const STAMEN_R = 0.7, STAMEN_H = 6.8, FLARE_R = 1.6, FLARE_H = 1.2;
const stamen = revolve(polygon([[0, -0.5], [STAMEN_R, -0.5], [STAMEN_R, STAMEN_H - FLARE_H], [FLARE_R, STAMEN_H], [0, STAMEN_H]])).translate([0, 0, floorZ]).named('stamen');
const stone = roundStone({ diameter: '2 mm', depth: '1.3 mm' });
const head = bezel({ stone }).translate([0, 0, floorZ + STAMEN_H - 0.1]);

const T = 1.0, RHO = 10, TILT = 12, R0 = 2.6, FLUTE_R = 0.45;
const half = [[0, 1.0], [0.9, 1.5], [1.8, 2.1], [2.7, 2.7], [3.6, 3.2], [4.5, 3.65], [5.4, 3.95], [6.3, 4.05], [7.2, 3.8], [7.9, 3.1], [8.5, 2.1], [9.0, 0.9]];
const outline = half.map(([v, h]) => [h, v]).concat(half.slice().reverse().map(([v, h]) => [-h, v]));
function flute(beta, s0, s1) {
  const b = beta * Math.PI / 180, d = RHO - T / 2, pts = [];
  for (let k = 0; k <= 12; k++) {
    const s = s0 + (s1 - s0) * k / 12, phi = s / RHO;
    pts.push([d * Math.sin(phi) * Math.sin(b), d * Math.sin(phi) * Math.cos(b), RHO - d * Math.cos(phi)]);
  }
  return sweep(FLUTE_R, pts);
}
const zMid = rimZ - 1.224;
const petals = [];
for (let i = 0; i < 5; i++) {
  const sheet = thicken({ id: 'petal_' + (i + 1), outline, thickness: T, surface: 'sphere', radius: RHO, round_corners: 0.5 });
  const one = union(sheet, flute(0, 0.3, 8.0), flute(25, 3.2, 7.0), flute(-25, 3.2, 7.0));
  petals.push(one.rotate([TILT, 0, 0]).translate([0, R0, zMid]).rotate([0, 0, i * 72]));
}
const petalRing = union(...petals).named('petals');
console.log('rimZ', rimZ, 'zMid', zMid, 'petals bounds', JSON.stringify(petalRing.bounds()));
return union(band, cup, petalRing, stamen, head);
